/* nepui — Menu
   A list of actions that opens from a trigger (a dropdown menu).
   One stylesheet for BOTH flavours; every part has a class and a data attribute.

     Content          .np-menu-content          [data-np-menu-content]
     Sub content      .np-menu-sub-content      [data-np-menu-sub-content]
     Group            .np-menu-group            [data-np-menu-group]
     Label            .np-menu-label            [data-np-menu-label]
     Item             .np-menu-item             [data-np-menu-item]
       destructive    .np-menu-item-destructive  or  data-variant="destructive"
       inset          data-inset  (or .np-menu-inset)
     Checkbox item    .np-menu-item.np-menu-checkbox-item
     Radio item       .np-menu-item.np-menu-radio-item
     Item indicator   .np-menu-item-indicator   (the check mark)
     Sub trigger      .np-menu-item.np-menu-sub-trigger
     Separator        .np-menu-separator        [data-np-menu-separator]
     Shortcut         .np-menu-shortcut         [data-np-menu-shortcut]

   React (Base UI Menu): Base UI positions the popup and sets data-open,
   data-closed, data-side, data-starting-style, data-ending-style and, on
   items, data-highlighted / data-disabled / data-checked.

   HTML (native Popover API + menu.js):
     <div class="np-menu">
       <button class="np-button np-button-outline" popovertarget="account">Open</button>
       <div id="account" class="np-menu-content" popover role="menu" aria-label="Account">
         <button class="np-menu-item" role="menuitem">Profile</button>
       </div>
     </div>
   The native popover gives the top layer, open / close, Escape and outside
   click. menu.js adds automatic positioning (flip, shift, max-height),
   keyboard navigation, typeahead, hover submenus and focus management.
   Without menu.js the popup still opens and closes, next to its trigger.

   Variables (set inline, or on any parent; read with fallbacks):
     --np-menu-bg            default: var(--np-popover, var(--np-background))
     --np-menu-color         default: var(--np-popover-foreground, var(--np-foreground))
     --np-menu-radius        default: var(--np-radius-md)
     --np-menu-min-width     default: 8rem
     --np-menu-item-radius   default: 0.375rem
     --np-menu-hover-bg      default: var(--np-accent, var(--np-muted))
     --np-menu-hover-color   default: var(--np-accent-foreground, var(--np-foreground))

   Tokens used: --np-background --np-foreground --np-muted --np-muted-foreground
   --np-border --np-destructive --np-radius-md
   Optional: --np-popover --np-popover-foreground --np-accent --np-accent-foreground */

/* ==========================================================================
   HTML wrappers and native popover positioning
   ========================================================================== */

.np-menu,
[data-np-menu],
.np-menu-sub,
[data-np-menu-sub] {
  position: relative;
  display: inline-block;
}

.np-menu-sub,
[data-np-menu-sub] {
  display: block;
}

/* A popover popup. menu.js sets `left`, `top`, `max-height`, `data-side` and
   `--transform-origin` on it. Without the script it stays at its static
   position, next to the trigger. */
:is(.np-menu-content, [data-np-menu-content])[popover] {
  position: fixed;
  inset: auto;
  margin: 0;
  border: 0;
  opacity: 0;
  transform: scale(0.95);
  transition:
    opacity 100ms ease,
    transform 100ms ease,
    display 100ms allow-discrete,
    overlay 100ms allow-discrete;
}

:is(.np-menu-content, [data-np-menu-content])[popover]:popover-open {
  opacity: 1;
  transform: none;
}

@starting-style {
  :is(.np-menu-content, [data-np-menu-content])[popover]:popover-open {
    opacity: 0;
    transform: scale(0.95);
  }
}

/* ==========================================================================
   Popup surface
   ========================================================================== */

.np-menu-positioner,
[data-np-menu-positioner] {
  isolation: isolate;
  z-index: 50;
  outline: none;
}

.np-menu-content,
[data-np-menu-content] {
  z-index: 50;
  box-sizing: border-box;
  min-width: max(var(--np-menu-min-width, 8rem), var(--anchor-width, 0px));
  max-height: var(--available-height, 24rem);
  overflow-x: hidden;
  overflow-y: auto;
  padding: 0.25rem;

  border-radius: var(--np-menu-radius, var(--np-radius-md));
  background: var(--np-menu-bg, var(--np-popover, var(--np-background)));
  color: var(
    --np-menu-color,
    var(--np-popover-foreground, var(--np-foreground))
  );
  box-shadow:
    0 0 0 1px color-mix(in oklch, var(--np-foreground) 10%, transparent),
    0 4px 6px -1px rgb(0 0 0 / 0.1),
    0 2px 4px -2px rgb(0 0 0 / 0.1);

  font-size: 0.875rem;
  outline: none;
  transform-origin: var(--transform-origin, top left);
}

.np-menu-sub-content,
[data-np-menu-sub-content] {
  --np-menu-min-width: 6rem;
  box-shadow:
    0 0 0 1px color-mix(in oklch, var(--np-foreground) 10%, transparent),
    0 10px 15px -3px rgb(0 0 0 / 0.1),
    0 4px 6px -4px rgb(0 0 0 / 0.1);
}

/* Base UI open / close transition (scale, fade, slide from the trigger) */
:is(.np-menu-content, [data-np-menu-content]):not([popover]) {
  transition:
    opacity 100ms ease,
    transform 100ms ease,
    translate 100ms ease;
}

:is(.np-menu-content, [data-np-menu-content]):not([popover]):is(
    [data-starting-style],
    [data-ending-style]
  ) {
  opacity: 0;
  transform: scale(0.95);
}

:is(.np-menu-content, [data-np-menu-content])[data-side="bottom"]:is(
    [data-starting-style],
    [data-ending-style]
  ) {
  translate: 0 -0.5rem;
}

:is(.np-menu-content, [data-np-menu-content])[data-side="top"]:is(
    [data-starting-style],
    [data-ending-style]
  ) {
  translate: 0 0.5rem;
}

:is(.np-menu-content, [data-np-menu-content]):is(
    [data-side="right"],
    [data-side="inline-end"]
  ):is([data-starting-style], [data-ending-style]) {
  translate: -0.5rem 0;
}

:is(.np-menu-content, [data-np-menu-content]):is(
    [data-side="left"],
    [data-side="inline-start"]
  ):is([data-starting-style], [data-ending-style]) {
  translate: 0.5rem 0;
}

/* ==========================================================================
   Group, label, separator
   ========================================================================== */

.np-menu-group,
[data-np-menu-group] {
  display: block;
}

.np-menu-label,
[data-np-menu-label] {
  padding: 0.25rem 0.375rem;
  color: var(--np-muted-foreground);
  font-size: 0.75rem;
  font-weight: 500;
}

.np-menu-separator,
[data-np-menu-separator] {
  height: 1px;
  margin: 0.25rem -0.25rem;
  border: 0;
  background: var(--np-border);
}

/* ==========================================================================
   Item
   ========================================================================== */

.np-menu-item,
[data-np-menu-item] {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.375rem;
  box-sizing: border-box;
  width: 100%;
  margin: 0;
  padding: 0.25rem 0.375rem;

  border: 0;
  border-radius: var(--np-menu-item-radius, 0.375rem);
  background: transparent;
  color: inherit;

  font: inherit;
  font-size: 0.875rem;
  line-height: 1.25rem;
  text-align: start;
  text-decoration: none;

  cursor: default;
  outline: none;
  -webkit-user-select: none;
  user-select: none;
}

:is(.np-menu-item, [data-np-menu-item]) svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(.np-menu-item, [data-np-menu-item]) svg:not([class*="size-"]) {
  width: 1rem;
  height: 1rem;
}

/* Highlighted: keyboard, hover, or an open submenu */
:is(.np-menu-item, [data-np-menu-item]):is(
  :focus,
  [data-highlighted],
  [data-popup-open],
  [data-open],
  :hover
) {
  background: var(--np-menu-hover-bg, var(--np-accent, var(--np-muted)));
  color: var(
    --np-menu-hover-color,
    var(--np-accent-foreground, var(--np-foreground))
  );
}

/* Disabled */
:is(.np-menu-item, [data-np-menu-item]):is(
  :disabled,
  [data-disabled],
  [aria-disabled="true"]
) {
  pointer-events: none;
  opacity: 0.5;
}

/* Inset: room for the check mark column of a neighbouring checkbox item */
:is(
  .np-menu-item,
  .np-menu-label,
  [data-np-menu-item],
  [data-np-menu-label]
)[data-inset],
.np-menu-inset {
  padding-inline-start: 1.75rem;
}

/* Destructive */
.np-menu-item-destructive,
:is(.np-menu-item, [data-np-menu-item])[data-variant="destructive"] {
  color: var(--np-destructive);
}

:is(
  .np-menu-item-destructive,
  :is(.np-menu-item, [data-np-menu-item])[data-variant="destructive"]
):is(:focus, [data-highlighted], [data-popup-open], [data-open], :hover) {
  background: var(
    --np-menu-destructive-bg,
    color-mix(in oklch, var(--np-destructive) 10%, transparent)
  );
  color: var(--np-destructive);
}

/* Checkbox and radio items: the check mark sits at the end */
:is(.np-menu-checkbox-item, .np-menu-radio-item) {
  padding-inline-end: 2rem;
}

.np-menu-item-indicator,
[data-np-menu-item-indicator] {
  position: absolute;
  inset-inline-end: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

/* Plain HTML renders the indicator always; hide it unless checked */
:is(.np-menu-checkbox-item, .np-menu-radio-item):is(
    [aria-checked="false"],
    [data-unchecked]
  )
  > :is(.np-menu-item-indicator, [data-np-menu-item-indicator]) {
  display: none;
}

/* Submenu trigger */
.np-menu-sub-chevron,
[data-np-menu-sub-chevron] {
  margin-inline-start: auto;
}

:dir(rtl) :is(.np-menu-sub-chevron, [data-np-menu-sub-chevron]) {
  transform: scaleX(-1);
}

/* ==========================================================================
   Shortcut
   ========================================================================== */

.np-menu-shortcut,
[data-np-menu-shortcut] {
  margin-inline-start: auto;
  color: var(--np-muted-foreground);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
}

:is(.np-menu-item, [data-np-menu-item]):is(
    :focus,
    [data-highlighted],
    [data-popup-open],
    [data-open],
    :hover
  )
  :is(.np-menu-shortcut, [data-np-menu-shortcut]) {
  color: var(
    --np-menu-hover-color,
    var(--np-accent-foreground, var(--np-foreground))
  );
}

/* ==========================================================================
   Reduced motion
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  :is(.np-menu-content, [data-np-menu-content]) {
    transition: none;
  }
}

:is(.dark, [data-theme="dark"]) :is(.np-menu-content, [data-np-menu-content]) {
  --np-menu-destructive-bg: color-mix(
    in oklch,
    var(--np-destructive) 20%,
    transparent
  );
}

@media (prefers-color-scheme: dark) {
  :root:not(.light, [data-theme="light"])
    :is(.np-menu-content, [data-np-menu-content]) {
    --np-menu-destructive-bg: color-mix(
      in oklch,
      var(--np-destructive) 20%,
      transparent
    );
  }
}

;(function (global) {
  "use strict"

  var WRAPPER = ".np-menu, [data-np-menu], .np-menu-sub, [data-np-menu-sub]"
  var SUB_WRAPPER = ".np-menu-sub, [data-np-menu-sub]"
  var ITEM =
    '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"]'
  var PADDING = 8
  var HOVER_OPEN_DELAY = 100
  var HOVER_CLOSE_GRACE = 150
  var TYPEAHEAD_RESET = 500

  /* ------------------------------------------------------------------ *
   * Positioning (pure, so it can be tested without a browser)
   * ------------------------------------------------------------------ */

  function clamp(value, min, max) {
    if (max < min) return min
    return Math.min(Math.max(value, min), max)
  }

  function physicalSide(side, rtl) {
    if (side === "inline-end") return rtl ? "left" : "right"
    if (side === "inline-start") return rtl ? "right" : "left"
    return side
  }

  /**
   * a    anchor rect   { left, top, right, bottom, width, height }
   * size popup size    { width, height }
   * vp   viewport      { width, height }
   * o    { side, align, sideOffset, alignOffset, rtl, padding }
   */
  function computePosition(a, size, vp, o) {
    var pad = o.padding
    var off = o.sideOffset
    var ao = o.alignOffset
    var rtl = o.rtl
    var side = physicalSide(o.side, rtl)
    var vertical = side === "top" || side === "bottom"
    var w = size.width
    var h = size.height
    var x
    var y
    var maxHeight

    if (vertical) {
      var below = vp.height - a.bottom - off - pad
      var above = a.top - off - pad

      if (side === "bottom" && h > below && above > below) side = "top"
      else if (side === "top" && h > above && below > above) side = "bottom"

      maxHeight = Math.max(0, side === "bottom" ? below : above)
      h = Math.min(h, maxHeight)
      y = side === "bottom" ? a.bottom + off : a.top - off - h

      if (o.align === "center") x = a.left + (a.width - w) / 2 + ao
      else if (o.align === "end") x = rtl ? a.left + ao : a.right - w - ao
      else x = rtl ? a.right - w - ao : a.left + ao

      x = clamp(x, pad, vp.width - w - pad)
    } else {
      var right = vp.width - a.right - off - pad
      var left = a.left - off - pad

      if (side === "right" && w > right && left > right) side = "left"
      else if (side === "left" && w > left && right > left) side = "right"

      maxHeight = Math.max(0, vp.height - pad * 2)
      h = Math.min(h, maxHeight)
      x = side === "right" ? a.right + off : a.left - off - w

      if (o.align === "center") y = a.top + (a.height - h) / 2 + ao
      else if (o.align === "end") y = a.bottom - h - ao
      else y = a.top + ao

      x = clamp(x, pad, vp.width - w - pad)
      y = clamp(y, pad, vp.height - h - pad)
    }

    var originX
    var originY
    if (vertical) {
      originX = clamp(a.left + a.width / 2 - x, 0, w)
      originY = side === "bottom" ? 0 : h
    } else {
      originX = side === "right" ? 0 : w
      originY = clamp(a.top + a.height / 2 - y, 0, h)
    }

    return {
      x: x,
      y: y,
      side: side,
      maxHeight: maxHeight,
      originX: originX,
      originY: originY,
    }
  }

  /* ------------------------------------------------------------------ *
   * Helpers
   * ------------------------------------------------------------------ */

  var uid = 0
  var openMenus = new Set()
  var frame = 0

  function isDisabled(el) {
    return (
      el.disabled === true ||
      el.getAttribute("aria-disabled") === "true" ||
      el.hasAttribute("data-disabled")
    )
  }

  function isOpen(content) {
    return content.matches(":popover-open")
  }

  function itemsOf(content) {
    return Array.prototype.filter.call(
      content.querySelectorAll(ITEM),
      function (item) {
        return item.closest('[role="menu"]') === content && !isDisabled(item)
      }
    )
  }

  function isSubTrigger(item) {
    return (
      item.hasAttribute("aria-haspopup") && item.hasAttribute("popovertarget")
    )
  }

  function rootOf(content) {
    var current = content
    for (;;) {
      var parent =
        current.parentElement && current.parentElement.closest('[role="menu"]')
      if (!parent) return current
      current = parent
    }
  }

  function closeOpenSubmenus(content) {
    var open = content.querySelectorAll(":popover-open")
    for (var i = open.length - 1; i >= 0; i--) open[i].hidePopover()
  }

  function schedulePlacement() {
    if (frame) return
    frame = requestAnimationFrame(function () {
      frame = 0
      openMenus.forEach(function (menu) {
        menu.place()
      })
    })
  }

  function num(value, fallback) {
    var n = parseFloat(value)
    return isNaN(n) ? fallback : n
  }

  /* ------------------------------------------------------------------ *
   * One menu (a root menu or a submenu)
   * ------------------------------------------------------------------ */

  function setup(wrapper) {
    if (wrapper.__npMenu) return

    var trigger = wrapper.querySelector(":scope > [popovertarget]")
    if (!trigger) return
    var content = document.getElementById(trigger.getAttribute("popovertarget"))
    if (!content) return

    wrapper.__npMenu = true
    var sub = wrapper.matches(SUB_WRAPPER)
    var parentContent = sub ? wrapper.closest('[role="menu"]') : null
    var focusOnOpen = null // "first" | "last" | null
    var hoverTimer = 0
    var typeahead = ""
    var typeaheadTimer = 0

    content.__npTrigger = trigger

    /* ARIA */
    if (!trigger.id) trigger.id = "np-menu-trigger-" + ++uid
    trigger.setAttribute("aria-haspopup", "menu")
    trigger.setAttribute("aria-controls", content.id)
    trigger.setAttribute("aria-expanded", "false")
    if (!content.hasAttribute("popover")) content.setAttribute("popover", "")
    if (!content.hasAttribute("role")) content.setAttribute("role", "menu")
    if (
      !content.hasAttribute("aria-label") &&
      !content.hasAttribute("aria-labelledby")
    ) {
      content.setAttribute("aria-labelledby", trigger.id)
    }
    content.setAttribute("tabindex", "-1")
    Array.prototype.forEach.call(
      content.querySelectorAll(ITEM),
      function (item) {
        item.setAttribute("tabindex", "-1")
      }
    )

    /* Positioning */
    function place() {
      var ds = content.dataset
      var r = trigger.getBoundingClientRect()
      var opts = {
        side: ds.npSide || (sub ? "inline-end" : "bottom"),
        align: ds.npAlign || "start",
        sideOffset: num(ds.npSideOffset, sub ? 0 : 4),
        alignOffset: num(ds.npAlignOffset, sub ? -4 : 0),
        rtl: getComputedStyle(content).direction === "rtl",
        padding: PADDING,
      }

      content.style.maxHeight = ""
      content.style.left = "0px"
      content.style.top = "0px"

      var size = { width: content.offsetWidth, height: content.offsetHeight }
      var vp = {
        width: document.documentElement.clientWidth,
        height: document.documentElement.clientHeight,
      }
      var p = computePosition(r, size, vp, opts)

      content.style.maxHeight = Math.floor(p.maxHeight) + "px"
      content.style.left = Math.round(p.x) + "px"
      content.style.top = Math.round(p.y) + "px"
      content.setAttribute("data-side", p.side)
      content.style.setProperty(
        "--transform-origin",
        p.originX + "px " + p.originY + "px"
      )
      content.style.setProperty("--anchor-width", r.width + "px")
    }

    var tracked = { place: place }

    content.addEventListener("toggle", function (event) {
      var open = event.newState === "open"
      trigger.setAttribute("aria-expanded", String(open))

      if (open) {
        place()
        openMenus.add(tracked)
        var items = itemsOf(content)
        if (focusOnOpen === "first" && items.length)
          items[0].focus({ preventScroll: true })
        else if (focusOnOpen === "last" && items.length)
          items[items.length - 1].focus({ preventScroll: true })
        else if (!sub) content.focus({ preventScroll: true })
        focusOnOpen = null
        if (sub) trigger.setAttribute("data-popup-open", "")
      } else {
        openMenus.delete(tracked)
        focusOnOpen = null
        if (sub) trigger.removeAttribute("data-popup-open")
      }
    })

    function openMenu(focus) {
      focusOnOpen = focus || null
      if (isOpen(content)) {
        var items = itemsOf(content)
        if (focus === "first" && items.length) items[0].focus()
        if (focus === "last" && items.length) items[items.length - 1].focus()
        focusOnOpen = null
      } else {
        content.showPopover()
      }
    }

    /* Trigger */
    trigger.addEventListener("click", function (event) {
      if (sub) {
        // A submenu opens and stays open; it is not toggled by a click.
        event.preventDefault()
        if (!isOpen(content)) openMenu("first")
        return
      }
      // Enter / Space fire a click with detail 0: focus the first item.
      if (event.detail === 0) focusOnOpen = "first"
    })

    trigger.addEventListener("keydown", function (event) {
      var rtl = getComputedStyle(trigger).direction === "rtl"
      var forward = rtl ? "ArrowLeft" : "ArrowRight"

      if (sub) {
        if (event.key === forward) {
          event.preventDefault()
          openMenu("first")
        }
        return
      }
      if (event.key === "ArrowDown") {
        event.preventDefault()
        openMenu("first")
      } else if (event.key === "ArrowUp") {
        event.preventDefault()
        openMenu("last")
      }
    })

    if (sub) {
      // Hover a submenu trigger: open after a short delay.
      trigger.addEventListener("pointerenter", function (event) {
        if (event.pointerType !== "mouse") return
        clearTimeout(hoverTimer)
        clearTimeout(parentContent.__npGrace)
        hoverTimer = setTimeout(function () {
          if (!isOpen(content)) openMenu(null)
        }, HOVER_OPEN_DELAY)
      })
      trigger.addEventListener("pointerleave", function () {
        clearTimeout(hoverTimer)
      })
      // Pointer reached the submenu: cancel the pending close of the parent.
      content.addEventListener("pointerenter", function () {
        clearTimeout(parentContent.__npGrace)
      })
    }

    /* Hover highlight follows the pointer (focus moves to the hovered item) */
    content.addEventListener("pointermove", function (event) {
      if (event.pointerType !== "mouse") return
      var item = event.target.closest(ITEM)
      if (
        !item ||
        item.closest('[role="menu"]') !== content ||
        isDisabled(item)
      )
        return
      if (document.activeElement !== item) item.focus({ preventScroll: true })

      if (!isSubTrigger(item)) {
        // Moving to a plain item closes an open submenu after a grace period,
        // so the pointer can cross other items on its way to the submenu.
        clearTimeout(content.__npGrace)
        content.__npGrace = setTimeout(function () {
          closeOpenSubmenus(content)
        }, HOVER_CLOSE_GRACE)
      }
    })

    content.addEventListener("pointerleave", function () {
      var active = document.activeElement
      if (
        active &&
        active !== content &&
        active.closest('[role="menu"]') === content
      ) {
        content.focus({ preventScroll: true })
      }
    })

    /* Choosing an item */
    content.addEventListener("click", function (event) {
      var item = event.target.closest(ITEM)
      if (
        !item ||
        item.closest('[role="menu"]') !== content ||
        isDisabled(item)
      )
        return
      if (isSubTrigger(item)) return

      var role = item.getAttribute("role")
      var checked

      if (role === "menuitemcheckbox") {
        checked = item.getAttribute("aria-checked") !== "true"
        item.setAttribute("aria-checked", String(checked))
      } else if (role === "menuitemradio") {
        var group =
          item.closest('[role="group"], [role="radiogroup"]') || content
        Array.prototype.forEach.call(
          group.querySelectorAll('[role="menuitemradio"]'),
          function (radio) {
            radio.setAttribute("aria-checked", String(radio === item))
          }
        )
        checked = true
      }

      item.dispatchEvent(
        new CustomEvent("np-menu:select", {
          bubbles: true,
          detail: {
            item: item,
